import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import AOS from "aos";
import "aos/dist/aos.css";
import "./RadarSweep.css";

// 🎵 Sound effects
const panicSound = new Audio("/panic-alert.mp3");
const voiceAlert = new Audio("/panic-voice.mp3");
const navSound = new Audio("/nav-hide.mp3"); // Optional whoosh sound

export default function ADIDroneHomePage() {
  const navigate = useNavigate();

  const [counts, setCounts] = useState({ fires: 0, alerts: 0, injured: 0 });
  const [hasPlayedVoice, setHasPlayedVoice] = useState(false);
  const [isVisible, setIsVisible] = useState(true);
  let lastScrollY = 0;

  // 🔁 Auto-hide navbar
  useEffect(() => {
    const handleScroll = () => {
      const currentScroll = window.scrollY;

      if (currentScroll > lastScrollY && currentScroll > 50) {
        setIsVisible(false);
        navSound.play().catch(() => {});
      } else {
        setIsVisible(true);
      }

      lastScrollY = currentScroll;
    };

    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  // ✨ Animate on scroll
  useEffect(() => {
    AOS.init({ duration: 800, once: true });
  }, []);

  // 🔢 Counter animation
  useEffect(() => {
    const animate = (key, target, delay = 80) => {
      let current = 0;
      const step = () => {
        if (current < target) {
          current++;
          setCounts((prev) => ({ ...prev, [key]: current }));
          setTimeout(step, delay);
        }
      };
      step();
    };
    animate("fires", 5);
    animate("alerts", 34);
    animate("injured", 12);
  }, []);

  // 🔊 Panic siren logic
  useEffect(() => {
    if (counts.alerts > 30) {
      panicSound.loop = true;
      panicSound.play().catch(() => {});
    } else {
      panicSound.pause();
      panicSound.currentTime = 0;
    }
  }, [counts.alerts]);

  // 🎙️ Voice alert once
  useEffect(() => {
    if (counts.alerts > 30 && !hasPlayedVoice) {
      voiceAlert.play().catch(() => {});
      setHasPlayedVoice(true);
    } else if (counts.alerts <= 30 && hasPlayedVoice) {
      setHasPlayedVoice(false);
    }
  }, [counts.alerts, hasPlayedVoice]);

  return (
    <div className="min-h-screen bg-black text-white font-sans relative overflow-hidden">

      {/* 🧊 Floating Glass Navbar */}
      <header className={`fixed top-0 left-0 w-full z-50 backdrop-blur-md bg-black/30 border-b border-cyan-800/20 shadow-sm transition-all duration-500 transform ${
        isVisible ? "translate-y-0 opacity-100" : "-translate-y-full opacity-0"
      }`}>
        <div className="flex justify-between items-center px-6 py-4">
          <h1 className="text-cyan-400 text-xl font-bold tracking-wide">🚁 ADI DRONE</h1>
          <nav className="space-x-4 text-sm text-cyan-200 font-medium">
            <button onClick={() => navigate("/")} className="hover:text-white transition">Home</button>
            <button onClick={() => navigate("/live-demo")} className="hover:text-white transition">Live Demo</button>
            <button onClick={() => navigate("/project")} className="hover:text-white transition">Project</button>
          </nav>
        </div>
      </header>

      {/* ✨ Floating Particle Background */}
      <div className="absolute inset-0 z-0 pointer-events-none">
        <div className="w-full h-full animate-pulse opacity-10 bg-[radial-gradient(circle,rgba(0,255,255,0.1)_1px,transparent_1px)] [background-size:20px_20px]" />
      </div>

      {/* 🛸 Hero Section */}
      <section className="text-center py-28 px-6 relative z-10 overflow-hidden">
        {/* 🔄 Radar Sweep */}
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 z-0">
          <div className="radar-container">
            <div className="radar-sweep"></div>
          </div>
        </div>

        {/* 🚁 Floating Drone */}
        <div className="absolute top-10 right-10 w-16 h-16 z-10 animate-bounce-slow">
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-full h-full text-cyan-400 drop-shadow-lg animate-fade-trail">
            <path strokeLinecap="round" strokeLinejoin="round" d="M2.25 12l8.25 8.25L18.75 12 10.5 3.75 2.25 12z" />
          </svg>
        </div>

        <div className="relative z-10">
          <h1 className="text-5xl font-bold text-cyan-400 mb-2 animate-pulse" data-aos="fade-up">
            ADI – THE THIRD EYE
          </h1>
          <p className="text-xl text-cyan-200 mb-6 uppercase tracking-wide" data-aos="fade-up">
            Vision of the Future
          </p>
          <p className="max-w-2xl mx-auto text-gray-300 mb-8" data-aos="zoom-in">
            AI-Powered Quadcopter for Crowd Control, Disaster Response, and Surveillance in India.
          </p>
          <div className="flex justify-center gap-4" data-aos="zoom-in-up">
            <button
              onClick={() => navigate("/live-demo")}
              className={`bg-cyan-500 hover:bg-cyan-600 hover:shadow-xl hover:shadow-cyan-400/80 text-white px-6 py-2 rounded-xl shadow-lg transition-all duration-300 animate-glow ${
                counts.alerts > 30 ? "animate-pulse bg-red-600 border-2 border-red-400" : ""
              }`}
            >
              ✨ LIVE DEMO
            </button>
            <button
              onClick={() => navigate("/project")}
              className="bg-gray-800 border border-cyan-500 text-cyan-200 hover:shadow-xl hover:shadow-cyan-300/70 px-6 py-2 rounded-xl transition-all duration-300"
            >
              🚀 VIEW PROJECT
            </button>
          </div>
        </div>
      </section>

      {/* 🧠 Feature Grid */}
      <section className="grid grid-cols-1 md:grid-cols-4 gap-6 px-6 py-12 text-center">
        {[
          ["Real-time Crowd Monitoring", "Heat-mapping", "/features/crowd"],
          ["Thermal Vision", "Fire Alerts", "/features/thermal"],
          ["Panic Detection", "(BlazePose)", "/features/panic"],
          ["Night Vision", "Low Light Enhancement", "/features/night"],
        ].map(([title, desc, link], i) => (
          <div
            key={i}
            data-aos="flip-left"
            onClick={() => navigate(link)}
            className="bg-gray-800 p-4 rounded-2xl hover:scale-105 hover:shadow-lg hover:shadow-cyan-400/40 transition-all cursor-pointer"
          >
            <h3 className="text-lg font-semibold text-cyan-300 mb-1">{title}</h3>
            <p className="text-sm text-gray-400">{desc}</p>
          </div>
        ))}
      </section>

      {/* 📺 Feed Preview */}
      <section className="grid grid-cols-2 md:grid-cols-4 gap-4 px-6 pb-12" data-aos="fade-up">
        {["RGB Feed", "Thermal View", "Depth Map", "GPS Map"].map((label, i) => (
          <div
            key={i}
            className="aspect-video bg-gray-900 rounded-xl flex items-center justify-center text-sm text-gray-400 hover:shadow-xl hover:shadow-cyan-400/30 transition-all"
          >
            {label}
          </div>
        ))}
      </section>

      {/* 📊 Stats Section */}
      <section className="text-center pb-12" data-aos="fade-in">
        <h2 className="text-2xl text-cyan-400 mb-6">Live Stats</h2>
        <div className="flex justify-center gap-12 text-lg text-gray-300">
          <div><span className="text-cyan-300 text-3xl block animate-pulse">{counts.fires}</span>Fires</div>
          <div><span className="text-cyan-300 text-3xl block animate-pulse">{counts.alerts}</span>Crowd Alerts</div>
          <div><span className="text-cyan-300 text-3xl block animate-pulse">{counts.injured}</span>Injured</div>
        </div>
      </section>

      {/* 🔧 Tech Stack */}
      <section className="py-10 px-6" data-aos="zoom-in">
        <div className="flex flex-wrap justify-center gap-6">
          {["YOLOv8", "BlazePose", "MediaPipe", "Raspberry Pi", "Mapbox", "WhisperX", "ThermalSim", "Zero-DCE++"].map(
            (tech, i) => (
              <span
                key={i}
                className="bg-gray-800 text-cyan-200 px-4 py-2 rounded-full text-sm shadow hover:shadow-lg hover:shadow-cyan-400/40 transition-all"
              >
                {tech}
              </span>
            )
          )}
        </div>
      </section>

      {/* 📬 Contact */}
      <section className="text-center py-12 px-6" data-aos="fade-up">
        <p className="text-gray-400">Prachi ma'am | erachi@example.com</p>
        <a
          href="/ADI-Drone-Report.pdf"
          download
          className="mt-4 inline-block bg-cyan-500 px-6 py-2 rounded-xl hover:bg-cyan-600 hover:shadow-lg hover:shadow-cyan-400 transition-all"
        >
          📥 Download Report
        </a>
      </section>
    </div>
  );
